import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.D7WGirly.js";const u=JSON.parse('{"title":"Migration","description":"","frontmatter":{},"headers":[],"relativePath":"migration.md","filePath":"migration.md"}'),r={name:"migration.md"};function n(s,e,d,c,l,p){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="migration" tabindex="-1">Migration <a class="header-anchor" href="#migration" aria-label="Permalink to &quot;Migration&quot;">​</a></h1><p>Version <strong>4.0.0</strong> contains the compatibility changes listed below and in the <a href="/changelog.html">changelog</a>. The major version reflects the Node.js 22 requirement and stricter validation. Upgrade only after reviewing your runtime and stored secrets.</p><h2 id="package-imports" tabindex="-1">Package imports <a class="header-anchor" href="#package-imports" aria-label="Permalink to &quot;Package imports&quot;">​</a></h2><p>The compiler now emits <code>dist/index.js</code>, matching the published entry point. Native ESM default imports now resolve to the callable <code>genTOTP</code> function. CommonJS named exports and TypeScript imports remain available.</p><p>The supported runtime is Node.js 22 or later. This package uses Node crypto and does not provide a standalone browser build.</p><h2 id="correctly-padded-codes" tabindex="-1">Correctly padded codes <a class="header-anchor" href="#correctly-padded-codes" aria-label="Permalink to &quot;Correctly padded codes&quot;">​</a></h2><p>All generated OTPs now contain exactly <code>digits</code> characters, including leading zeroes. Keep submitted codes as strings. Previously shortened codes are rejected by verification.</p><h2 id="strict-inputs" tabindex="-1">Strict inputs <a class="header-anchor" href="#strict-inputs" aria-label="Permalink to &quot;Strict inputs&quot;">​</a></h2><p>The generation and verification APIs reject invalid digit counts, periods, counters, timestamps, encodings, algorithms, and windows. Verification windows are capped at 1000.</p><p>Base32 decoding now returns complete bytes. Keys whose decoded byte length was not a multiple of five may have produced incorrect codes or thrown before this fix. Invalid padding and unused bits are rejected. Hex input must contain whole bytes.</p><p>Review any stored noncanonical secrets before releasing. Correct canonical secrets and standard settings retain their RFC outputs.</p><h2 id="authenticator-uris" tabindex="-1">Authenticator URIs <a class="header-anchor" href="#authenticator-uris" aria-label="Permalink to &quot;Authenticator URIs&quot;">​</a></h2><p>Secrets are normalized to uppercase, unpadded Base32. Empty labels, labels containing colons, fractional periods, digit counts outside 6/8, and algorithms outside SHA-1/SHA-256/SHA-512 are rejected. The default enrollment settings are unchanged.</p><h2 id="documentation-links" tabindex="-1">Documentation links <a class="header-anchor" href="#documentation-links" aria-label="Permalink to &quot;Documentation links&quot;">​</a></h2><p>The VitePress site keeps <code>otp.js.org</code>. Links from the former Docsify site to its home and changelog are redirected to the new guides.</p>',15)])])}const m=t(r,[["render",n]]);export{u as __pageData,m as default};
